import falcon
from wsgiref import simple_server
from taf.gnb.oam.ne3s.ws.components.connection.netact_server.resources import (FilesResource,
                                                                               NotificationResource)


class NetactServer(object):
    def __init__(self, notification_queue, port=8080):
        notification_resource = NotificationResource(notification_queue)
        self.port = port
        self.address = ""
        self.app = falcon.API(media_type='text/xml; charset=UTF-8')

        # GET requests on '/files/*' endpoint should be served by sending file
        handler = FilesResource().on_get
        self.app.add_sink(handler, '/files')
        # NE3SFeedback will be sent to NE3SOperationNotificationService
        self.app.add_route('/notifications/{filter_name}/{msg_group}',
                           notification_resource)
        self.httpd = None

    def run(self):
        self.httpd = simple_server.make_server(self.address, self.port, self.app)
        self.httpd.serve_forever()

    def shutdown(self):
        if self.httpd is not None:
            try:
                self.httpd.shutdown()
            except Exception:
                pass

            try:
                self.httpd.server_close()
            except Exception:
                pass
